const items = $input.all();
const leads = items.map(i => i.json).filter(j => j.Title || j.title);
// Normalize to API format (lowercase keys) but keep n8n sheet keys as fallback - server handles both
const normalized = leads.map(l => ({
  title: l.Title || l.title,
  link: l.Link || l.link,
  source: l.Source || l.source,
  country: l.Country || l.country,
  status: l.Status || l.status || 'New',
  matched_keyword: l['Matched Keyword'] || l.matched_keyword,
  snippet: l.Snippet || l.snippet,
  date: l.Date || l.date || new Date().toISOString()
}));
return [{ json: { leads: normalized } }];
